assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
OUT.mkdir(parents=True, exist_ok=True)
n = 0
for cid in IDS:
    d = P[cid]
    rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    assert set(rec.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
    assert 0.0 <= rec["confidence"] <= 1.0
    t = rec["trigger"]
    assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed"))
    (OUT / f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    n += 1
assert n == 20, n
print("WROTE", n)
ly = [c for c in IDS if c.startswith("YM-")]
for k in ("changed_main", "reserve_used", "disputed"):
    print(k, sum(1 for c in ly if P[c]["trigger"][k]), "/", len(ly))
